import{_ as a,o as i,c as e,an as t}from"./chunks/framework.BZkRsxf_.js";const k=JSON.parse('{"title":"Run with real meteorology","description":"","frontmatter":{},"headers":[],"relativePath":"getting_started/first_run.md","filePath":"getting_started/first_run.md","lastUpdated":null}'),n={name:"getting_started/first_run.md"};function r(p,s,l,o,h,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="Run-with-real-meteorology" tabindex="-1">Run with real meteorology <a class="header-anchor" href="#Run-with-real-meteorology" aria-label="Permalink to &quot;Run with real meteorology {#Run-with-real-meteorology}&quot;">​</a></h1><p>The <a href="/AtmosTransport.jl/dev/getting_started/quickstart#Quickstart">Quickstart</a> uses synthetic forcing so that everyone can run it. A scientific run uses the same runner and TOML structure, but points at one or more transport binaries generated from ERA5 or GEOS meteorology.</p><h2 id="What-you-need" tabindex="-1">What you need <a class="header-anchor" href="#What-you-need" aria-label="Permalink to &quot;What you need {#What-you-need}&quot;">​</a></h2><p>A forward run has three inputs:</p><ol><li><p><strong>Transport binaries</strong>—one or more version-4 files produced by the current preprocessor. They contain grid geometry, air mass, mass fluxes, timing, and any requested diffusion or convection fields.</p></li><li><p><strong>A run TOML</strong>—selects precision, architecture, operators, tracers, initial conditions, emissions, and output.</p></li><li><p><strong>Optional scientific data</strong>—file-backed initial conditions or emissions inventories referenced by the TOML.</p></li></ol><p>Raw ERA5 GRIB or GEOS NetCDF is not opened by the runtime. See <a href="/AtmosTransport.jl/dev/preprocessing/overview#Preprocessing-overview">Preprocessing overview</a> when you need to create transport binaries.</p><h2 id="1.-Inspect-the-forcing-first" tabindex="-1">1. Inspect the forcing first <a class="header-anchor" href="#1.-Inspect-the-forcing-first" aria-label="Permalink to &quot;1. Inspect the forcing first {#1.-Inspect-the-forcing-first}&quot;">​</a></h2><p>Before writing a run configuration, inspect one file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/diagnostics/inspect_transport_binary.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    /path/to/era5_transport_20211201_float32.bin</span></span></code></pre></div><p>Confirm:</p><ul><li><p><code>format_version</code> is 4 (older files are rejected);</p></li><li><p><code>grid_type</code> and vertical level count match the intended experiment;</p></li><li><p><code>mass_basis</code> is <code>dry</code> for the standard runtime;</p></li><li><p>the required capability is present for every requested operator—for example, TM5 convection needs <code>entu</code>, <code>detu</code>, <code>entd</code>, and <code>detd</code>.</p></li></ul><p>This check catches incompatible data before model allocation or GPU startup.</p><h2 id="2.-Copy-the-canonical-template" tabindex="-1">2. Copy the canonical template <a class="header-anchor" href="#2.-Copy-the-canonical-template" aria-label="Permalink to &quot;2. Copy the canonical template {#2.-Copy-the-canonical-template}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/examples/minimal_template.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_run.toml</span></span></code></pre></div><p>The template uses the current section names. Replace its synthetic input and output paths, then adjust the physics and tracers for the experiment.</p><h3 id="Input:-explicit-files" tabindex="-1">Input: explicit files <a class="header-anchor" href="#Input:-explicit-files" aria-label="Permalink to &quot;Input: explicit files {#Input:-explicit-files}&quot;">​</a></h3><p>Use an explicit list for a short run or files without a date naming pattern:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">binary_paths = [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;/data/transport/era5_transport_20211201_float32.bin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;/data/transport/era5_transport_20211202_float32.bin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="Input:-folder-and-date-range" tabindex="-1">Input: folder and date range <a class="header-anchor" href="#Input:-folder-and-date-range" aria-label="Permalink to &quot;Input: folder and date range {#Input:-folder-and-date-range}&quot;">​</a></h3><p>Use folder expansion for daily production files:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">folder = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$ATMOSTRANSPORT_DATA_ROOT/met/era5/ll72x37/transport&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">start_date = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2021-12-01&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">end_date = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2021-12-10&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add this only when the filename needs an exact pattern:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># file_pattern = &quot;era5_transport_{YYYYMMDD}_float32.bin&quot;</span></span></code></pre></div><p>The range is inclusive. The runner verifies that every date exists and rejects duplicates or gaps.</p><h3 id="Architecture-and-precision" tabindex="-1">Architecture and precision <a class="header-anchor" href="#Architecture-and-precision" aria-label="Permalink to &quot;Architecture and precision {#Architecture-and-precision}&quot;">​</a></h3><p>Start on CPU when validating a new configuration:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">architecture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">use_gpu = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cpu&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">numerics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float_type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Float32&quot;</span></span></code></pre></div><p>After the CPU smoke run succeeds, set <code>use_gpu = true</code> and choose <code>&quot;cuda&quot;</code>, <code>&quot;metal&quot;</code>, or <code>&quot;auto&quot;</code>. Metal requires <code>Float32</code>.</p><h3 id="Operators" tabindex="-1">Operators <a class="header-anchor" href="#Operators" aria-label="Permalink to &quot;Operators {#Operators}&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">advection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scheme = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;slopes&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">diffusion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;none&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">convection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;none&quot;</span></span></code></pre></div><p>Operator selection must agree with the binary capabilities. Omitting an optional physics block or using <code>kind = &quot;none&quot;</code> selects its typed no-op. See <a href="/AtmosTransport.jl/dev/concepts/operators#Operator-concepts">Operators</a> for the available schemes and <a href="/AtmosTransport.jl/dev/config/toml_schema#TOML-schema">TOML schema</a> for every key.</p><h3 id="Tracers-and-output" tabindex="-1">Tracers and output <a class="header-anchor" href="#Tracers-and-output" aria-label="Permalink to &quot;Tracers and output {#Tracers-and-output}&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tracers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">co2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;uniform&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400.0e-6</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # dry mol/mol = 400 ppm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">output</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cadence_hours = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$ATMOSTRANSPORT_DATA_ROOT/output/my_run.nc&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">split = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;single&quot;</span></span></code></pre></div><p>Tracer initial conditions are dry volume mixing ratios. Internally the model converts them to conservative <code>mixing ratio × carrier-air-mass</code> storage. Output converts back to mixing ratio and writes the mass diagnostics needed to reproduce column means.</p><h2 id="3.-Validate-and-run" tabindex="-1">3. Validate and run <a class="header-anchor" href="#3.-Validate-and-run" aria-label="Permalink to &quot;3. Validate and run {#3.-Validate-and-run}&quot;">​</a></h2><p>The command-line runner performs inexpensive configuration checks before opening the full simulation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run_transport.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_run.toml</span></span></code></pre></div><p>The script may restart itself with two Julia threads so NetCDF writes can overlap computation. Set <code>ATMOSTR_NO_AUTO_THREADS=1</code> only when debugging a single-threaded path.</p><p>A successful startup summary identifies the choices that matter:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Driven runtime</span></span>
<span class="line"><span>|-- grid:      ...</span></span>
<span class="line"><span>|-- numerics:  scheme=Slopes, FT=Float32, backend=CPU</span></span>
<span class="line"><span>|-- physics:   diffusion=NoDiffusion, convection=NoConvection</span></span>
<span class="line"><span>|-- schedule:  window_dt=3600s, steps/window=..., binaries=...</span></span>
<span class="line"><span>|-- tracers:   co2</span></span>
<span class="line"><span>\`-- output:    .../my_run.nc</span></span></code></pre></div><p>At completion, check the final air-mass and per-tracer storage-budget lines. Their tolerance depends on precision and enabled sources/sinks; unexplained drift in a closed advection-only run is a failure, not a cosmetic warning.</p><h2 id="Data-roots" tabindex="-1">Data roots <a class="header-anchor" href="#Data-roots" aria-label="Permalink to &quot;Data roots {#Data-roots}&quot;">​</a></h2><p><code>$ATMOSTRANSPORT_DATA_ROOT</code> defaults to <code>~/data/AtmosTransport</code>. Set it once to keep configs portable across machines:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ATMOSTRANSPORT_DATA_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/scratch/$USER/AtmosTransport</span></span></code></pre></div><p>Paths beginning with <code>~/</code> and environment variables are expanded by the runtime. Relative paths are interpreted from the directory where the command is run, which is another reason to run from the repository root.</p><h2 id="Create-current-forcing-from-raw-data" tabindex="-1">Create current forcing from raw data <a class="header-anchor" href="#Create-current-forcing-from-raw-data" aria-label="Permalink to &quot;Create current forcing from raw data {#Create-current-forcing-from-raw-data}&quot;">​</a></h2><p>The canonical preprocessing command is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --threads=8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    scripts/preprocessing/preprocess_transport_binary.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    config/preprocessing/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">source-and-gri</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --day</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2021-12-01</span></span></code></pre></div><p>Use <code>--start</code> and <code>--end</code> where the selected source supports a range. The preprocessor performs dry-air conversion, topology/vertical transforms, continuity balancing, adaptive substep selection, and write-time replay and positivity gates before committing the binary.</p><p>Choose the source-specific guide next:</p><ul><li><p><a href="/AtmosTransport.jl/dev/preprocessing/spectral_era5#ERA5-spectral-path">ERA5 spectral path</a> for lat-lon, reduced Gaussian, or cubed sphere.</p></li><li><p><a href="/AtmosTransport.jl/dev/preprocessing/geos_native_cs#GEOS-native-cubed-sphere">GEOS native cubed-sphere</a> for GEOS-IT or GEOS-FP native panels.</p></li><li><p><a href="/AtmosTransport.jl/dev/config/data_sources#Data-sources">Data sources</a> for authentication and raw-file layout.</p></li></ul><h2 id="Common-first-run-failures" tabindex="-1">Common first-run failures <a class="header-anchor" href="#Common-first-run-failures" aria-label="Permalink to &quot;Common first-run failures {#Common-first-run-failures}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Message or symptom</th><th style="text-align:right;">Meaning and first action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>unsupported transport binary version</code></td><td style="text-align:right;">Regenerate the forcing with the current version-4 preprocessor.</td></tr><tr><td style="text-align:right;"><code>resolved path does not exist</code></td><td style="text-align:right;">Check the active data root and run from the repository root.</td></tr><tr><td style="text-align:right;">Missing convection/diffusion payload</td><td style="text-align:right;">The preprocessing config did not include the fields required by the selected operator.</td></tr><tr><td style="text-align:right;">GPU backend unavailable</td><td style="text-align:right;">Set CPU in TOML, verify the run, then diagnose the optional backend separately.</td></tr><tr><td style="text-align:right;">Date range has gaps</td><td style="text-align:right;">Add the missing daily binary or use an explicit <code>binary_paths</code> list.</td></tr><tr><td style="text-align:right;">Extreme CFL or positivity failure</td><td style="text-align:right;">Inspect the binary schedule and preprocessing gates; do not work around it by suppressing the error.</td></tr></tbody></table><h2 id="Next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#Next-steps" aria-label="Permalink to &quot;Next steps {#Next-steps}&quot;">​</a></h2><ul><li><p><a href="/AtmosTransport.jl/dev/getting_started/inspecting_output#Inspecting-output">Inspecting output</a> explains variables and dimension order.</p></li><li><p><a href="/AtmosTransport.jl/dev/concepts/architecture#Architecture-tour">Architecture tour</a> connects the runner to the typed source structure.</p></li><li><p><a href="/AtmosTransport.jl/dev/config/toml_schema#TOML-schema">TOML schema</a> is the complete configuration reference.</p></li></ul>`,53)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
